async function loadHazards(){if(cache.hazards)return cache.hazards;if(cache.hazardPromise)return cache.hazardPromise;cache.hazardPromise=fetch('/bullpen-production-models.json',{cache:'no-store'}).then(r=>r.ok?r.json():null).then(x=>cache.hazards=x?.models||null).catch(()=>null);return cache.hazardPromise}
loadHazards();
function hazardAtBoundary(live,side,pid,{outs,mask,nextLineupPos,bf,score}){const m=cache.hazards?.in_inning_removal;if(!m)return null;const ls=live?.linescore||{},box=live?.boxscore?.teams?.[side]||{},ids=(box.pitchers||[]).map(Number),starter=ids[0]===Number(pid)?1:0;const half=String(ls.isTopInning===false?'1':'0');return transform(m,[Number(ls.currentInning||1),Number(bf||0),Number(score),half,String(outs),String(mask),String(nextLineupPos),String(starter)])}
